34	// An ordinary property, so it survives Eta's include(), which copies a
35	// partial's data: a partial rendered inside the page sees the query too.
36	function withQuery(data, query) {
37	  if (data && typeof data === 'object') data.$query = query;
38	  return data ?? { $query: query };
39	}
